51	    /**
52	     * Computes an owner's numeric membership level, assigned at creation. The level starts at 1, gains 1
53	     * when an email is present, gains a further 1 when {@code namesakeCount} is 0, and is capped at
54	     * {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure).
55	     *
56	     * @param owner the owner whose level is being computed
57	     * @return the membership level (between 1 and {@value #MAX_MEMBERSHIP_LEVEL} inclusive)
58	     */
59	    protected Integer membershipLevel(Owner owner) {
60	        int level = 1;
61	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
62	            level++;
63	        }
64	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
65	            level++;
66	        }
67	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
68	    }
69	
70	    /**
71	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits contained in
72	     * the owner's {@code customerCode}. Non-digit characters (such as the letters and dashes in the code) are
73	     * skipped; the rightmost digit is doubled and every second digit thereafter, digits exceeding 9 after
74	     * doubling have 9 subtracted, and the check digit is {@code (10 - sum % 10) % 10}.
75	     *
76	     * @param owner the owner whose check digit is being computed
77	     * @return the Luhn check digit (between 0 and 9 inclusive) over the customer code's digits
78	     */
79	    protected Integer checkDigit(Owner owner) {
80	        String code = owner.getCustomerCode() == null ? "" : owner.getCustomerCode();
81	        int sum = 0;
82	        boolean dbl = true;
83	        for (int i = code.length() - 1; i >= 0; i--) {
84	            char c = code.charAt(i);
85	            if (c < '0' || c > '9') {
86	                continue;
87	            }
88	            int d = c - '0';
89	            if (dbl) {
90	                d *= 2;
91	                if (d > 9) {
92	                    d -= 9;
93	                }
94	            }
95	            sum += d;
96	            dbl = !dbl;
97	        }
98	        return (10 - (sum % 10)) % 10;
99	    }
100	
101	    /**
102	     * Derives an owner's preferred contact channel at read time: {@code 'EMAIL'} when an email address is
103	     * present, otherwise {@code 'PHONE'}.
104	     *
105	     * @param owner the owner whose contact preference is being computed
106	     * @return {@code 'EMAIL'} when the owner has a non-blank email, otherwise {@code 'PHONE'}
107	     */
108	    protected String contactPreference(Owner owner) {
109	        return (owner.getEmail() != null && !owner.getEmail().isBlank()) ? "EMAIL" : "PHONE";
110	    }
111	
112	    /**
113	     * Derives an owner's age band from {@code birthDate}, measured against {@code registrationDate}: the
114	     * completed years between the two dates place the owner in {@code 'MINOR'} (under 18), {@code 'ADULT'}
115	     * (18 to 64 inclusive) or {@code 'SENIOR'} (65 or over). Returns {@code null} when the owner has no
116	     * {@code birthDate}, so the field is simply absent for owners created without one.
117	     *
118	     * @param owner the owner whose age band is being derived
119	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when no birth date is set
120	     */
121	    protected String ageBand(Owner owner) {
122	        if (owner.getBirthDate() == null) {
123	            return null;
124	        }
125	        LocalDate reference = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
126	        int years = Period.between(owner.getBirthDate(), reference).getYears();
127	        if (years < 18) {
128	            return "MINOR";
129	        }
130	        if (years < 65) {
131	            return "ADULT";
132	        }
133	        return "SENIOR";
134	    }
135	
136	    /**
137	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
138	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
139	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'}). This is the single key used for duplicate detection,
140	     * so the value returned here matches the one the create endpoint compares.
141	     *
142	     * @param owner the owner whose identity key is being derived
143	     * @return the owner's identity key
144	     */
145	    protected String identityKey(Owner owner) {
146	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
147	        String email = owner.getEmail() == null ? "" : owner.getEmail();
148	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
149	        return telephone + "|" + email + "|" + householdId;
150	    }
151	
152	    /**
153	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
154	     * national digits grouped in threes from the left (e.g. {@code '+61412345678'} becomes
155	     * {@code '+61 412 345 678'}). The raw {@code telephone} is left untouched in E.164 form. Values that are
156	     * {@code null} or not in E.164 form (no leading {@code '+'}) are returned unchanged.
157	     * <p>
158	     * The country code is split off using the codes the application recognises: {@code '+1'} (NANP) is a
159	     * single digit and any other number is assumed to carry the default {@code '+61'}-style two-digit code.
160	     *
161	     * @param owner the owner whose telephone is being formatted
162	     * @return the human-formatted telephone, or the raw value when it is {@code null} or not E.164
163	     */
164	    protected String telephoneDisplay(Owner owner) {
165	        String telephone = owner.getTelephone();
166	        if (telephone == null || !telephone.startsWith("+")) {
167	            return telephone;
168	        }
169	        String digits = telephone.substring(1);
170	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
171	        if (digits.length() <= countryCodeLength) {
172	            return telephone;
173	        }
174	        String countryCode = digits.substring(0, countryCodeLength);
175	        String national = digits.substring(countryCodeLength);
176	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
177	        for (int i = 0; i < national.length(); i++) {
178	            if (i % 3 == 0) {
179	                grouped.append(' ');
180	            }
181	            grouped.append(national.charAt(i));
182	        }
183	        return grouped.toString();
184	    }
